    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
def f(g):
    g=[r[:] for r in g]; h=len(g); w=len(g[0])
    bl=[]
    for r in range(h-2):
        for c in range(w-2):
            v=g[r][c]
            if v!=0 and all(g[i][j]==v for i in range(r,r+3) for j in range(c,c+3)):
                bl.append((r+1,c+1,v))
    out=[r[:] for r in g]
    for rr,cc,v in bl:
        for c in range(w): out[rr][c]=v
        for r in range(h): out[r][cc]=v
    for i in range(len(bl)):
        for j in range(i+1,len(bl)):
            a,b=bl[i],bl[j]
            if a[2]!=b[2]:
                out[a[0]][b[1]]=0
                out[b[0]][a[1]]=0
    return out
for k in ['Demo pair 1','Demo pair 2','Demo pair 3','Demo pair 4']:
    A=f(G[k+' input']); B=G[k+' output']
    dd=[(r,c,A[r][c],B[r][c]) for r in range(len(A)) for c in range(len(A[0])) if A[r][c]!=B[r][c]]
    print(k,dd)
T=f(G['Test input'])
